options.afterRender:
const root = context.element.querySelector('.s3drill-root') || context.element;
const rv = context.grafana.replaceVariables;
const project = rv('${project}');
const owner = rv('${owner}');

if (!window.__s3drill) window.__s3drill = {};
const S = window.__s3drill;

function isAll(v){ return !v || v==='All' || v==='$__all' || v==='.*' || v.indexOf('{')>=0 || v.indexOf('|')>=0; }
const projClean = isAll(project) ? '' : project;
if (S.lastProject !== project) { S.path = projClean; S.lastProject = project; }
if (S.path === undefined) S.path = projClean;

function fmt(b){ if(b==null)return '-'; if(b>=1099511627776)return (b/1099511627776).toFixed(1)+' TiB'; if(b>=1073741824)return (b/1073741824).toFixed(1)+' GiB'; if(b>=1048576)return (b/1048576).toFixed(1)+' MiB'; if(b>=1024)return (b/1024).toFixed(0)+' KiB'; return b+' B';}
function fmtN(n){ if(n==null)return '-'; if(n>=1e6)return (n/1e6).toFixed(1)+'M'; if(n>=1e3)return (n/1e3).toFixed(1)+'K'; return ''+n;}

function render(data){
  let h='<div style="font-family:sans-serif;font-size:13px;color:#e5e7eb">';
  h+='<div style="padding:6px 4px;color:#9ca3af;font-size:12px">\u{1F4C2} '+(S.path||'(전체 프로젝트)')+'</div>';
  h+='<table style="width:100%;border-collapse:collapse"><thead><tr style="text-align:left;color:#9ca3af;border-bottom:1px solid #374151">';
  h+='<th style="padding:5px 8px">폴더</th><th style="padding:5px 8px">소유자</th><th style="padding:5px 8px;text-align:right">용량</th><th style="padding:5px 8px;text-align:right">파일수</th></tr></thead><tbody>';
  if (S.path){
    h+='<tr data-up="1" style="cursor:pointer;color:#60a5fa"><td style="padding:5px 8px">\u2B06 .. (상위 폴더로)</td><td></td><td style="text-align:right">-</td><td style="text-align:right">-</td></tr>';
  }
  for (const it of data){
    if (it.name && it.name.indexOf('상위 폴더')>=0) continue;
    h+='<tr data-fp="'+encodeURIComponent(it.fullpath||'')+'" style="cursor:pointer;border-bottom:1px solid #1f2937">';
    h+='<td style="padding:5px 8px;color:#f3f4f6">\u{1F4C1} '+it.name+'</td>';
    h+='<td style="padding:5px 8px;color:#cbd5e1">'+(it.owner||'')+'</td>';
    h+='<td style="padding:5px 8px;text-align:right">'+fmt(it.bytes)+'</td>';
    h+='<td style="padding:5px 8px;text-align:right;color:#cbd5e1">'+fmtN(it.objects)+'</td></tr>';
  }
  h+='</tbody></table></div>';
  root.innerHTML=h;
  root.querySelectorAll('tr[data-fp]').forEach(function(tr){
    tr.addEventListener('click',function(){ S.path=decodeURIComponent(tr.getAttribute('data-fp')); load(); });
    tr.addEventListener('mouseover',function(){ tr.style.background='#1f2937'; });
    tr.addEventListener('mouseout',function(){ tr.style.background=''; });
  });
  const up=root.querySelector('tr[data-up]');
  if(up){
    up.addEventListener('click',function(){ const p=(S.path||'').split('/'); p.pop(); S.path=p.join('/'); load(); });
    up.addEventListener('mouseover',function(){ up.style.background='#1f2937'; });
    up.addEventListener('mouseout',function(){ up.style.background=''; });
  }
}

function load(){
  root.innerHTML='<div style="padding:12px;color:#9ca3af">로딩중...</div>';
  const url='/api/datasources/proxy/uid/afqyi1v4btypsf/api/tree?project='+encodeURIComponent(project)+'&subpath='+encodeURIComponent(S.path||'')+'&owner='+encodeURIComponent(owner);
  fetch(url,{credentials:'include'}).then(function(r){return r.json();}).then(function(d){ render(Array.isArray(d)?d:[]); }).catch(function(e){ root.innerHTML='<div style="color:#f87171;padding:12px">오류: '+e.message+'</div>'; });
}
load();
